const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Walvis Bay, Namibia
  const geometry = ee.Geometry.Point([14.5, -22.95]);
  const buffer = geometry.buffer(20000); // 20km buffer

  // Helper: mask clouds in Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    return image.updateMask(qa.bitwiseAnd(cloudBitMask).eq(0)
                           .and(qa.bitwiseAnd(cirrusBitMask).eq(0)));
  }

  // Helper: calculate NDVI
  function addNDVI(image) {
    return image.addBands(
      image.normalizedDifference(['B8', 'B4']).rename('NDVI')
    );
  }

  // Collect Sentinel-2 data for February 2021
  const feb2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer)
    .filterDate('2021-02-01', '2021-02-28')
    .map(maskS2clouds)
    .map(addNDVI);

  const feb2021Count = feb2021.size().getInfo();
  print('Feb 2021 Images:', feb2021Count);

  if (feb2021Count === 0) {
    print('No data for Feb 2021');
    print('C1');
    return;
  }

  // Calculate February 2021 mean NDVI
  const feb2021NDVI = feb2021.select('NDVI')
    .reduce(ee.Reducer.mean())
    .reduceRegion(
      { reducer: ee.Reducer.mean(), geometry: buffer, scale: 1000, maxPixels: 1e9 }
    );

  const val2021 = feb2021NDVI.get('NDVI_mean').getInfo();
  print('Feb 2021 Mean NDVI:', val2021 !== null ? val2021.toFixed(4) : 'null');

  if (val2021 === null || isNaN(val2021) || val2021 < -1 || val2021 > 1) {
    print('C3');
    return;
  }

  // Collect historical February data (2010-2020)
  let historicalNDVI = [];
  let validYears = 0;

  for (let year = 2010; year <= 2020; year++) {
    let col;

    if (year >= 2015) {
      // Sentinel-2
      col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(buffer)
        .filterDate(`${year}-02-01`, `${year}-02-28`)
        .map(maskS2clouds)
        .map(addNDVI);
    } else if (year >= 2013) {
      // Landsat 8
      col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(buffer)
        .filterDate(`${year}-02-01`, `${year}-02-28`)
        .map(function(img) {
          return img.updateMask(img.select('QA_PIXEL').bitwiseAnd(1).eq(0));
        })
        .map(function(img) {
          return img.addBands(img.normalizedDifference(['B5', 'B4']).rename('NDVI'));
        });
    } else {
      // Landsat 7 or 5
      col = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(buffer)
        .filterDate(`${year}-02-01`, `${year}-02-28`)
        .map(function(img) {
          return img.updateMask(img.select('QA_PIXEL').bitwiseAnd(1).eq(0));
        })
        .map(function(img) {
          return img.addBands(img.normalizedDifference(['B4', 'B3']).rename('NDVI'));
        });
    }

    const count = col.size().getInfo();
    if (count > 0) {
      const ndvi = col.select('NDVI')
        .reduce(ee.Reducer.mean())
        .reduceRegion(
          { reducer: ee.Reducer.mean(), geometry: buffer, scale: 1000, maxPixels: 1e9 }
        )
        .get('NDVI_mean')
        .getInfo();

      if (ndvi !== null && !isNaN(ndvi) && ndvi >= -1 && ndvi <= 1) {
        historicalNDVI.push(ndvi);
        validYears++;
        print(`Feb ${year}: NDVI=${ndvi.toFixed(4)}`);
      }
    }
  }

  print(`Valid years: ${validYears}`);

  if (validYears === 0) {
    print('No valid historical data');
    print('C1');
    return;
  }

  const avgHistorical = historicalNDVI.reduce((a, b) => a + b, 0) / validYears;
  print(`Feb 2010-2020 Avg NDVI: ${avgHistorical.toFixed(4)}`);
  print(`Feb 2021 NDVI: ${val2021.toFixed(4)}`);

  if (val2021 > avgHistorical) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
